  ('la-pt', 'la-f025', 'frase', 'A1', array['primeiros passos']::text[], null, 'd851a03e', array['A glória de Deus está nas alturas.', 'Deus está na glória das alturas.', 'Glória a Deus nas alturas.', 'Glória ao Deus das alturas.', 'Glória aos deuses das alturas.']::text[]),
  ('la-pt', 'la-f056', 'frase', 'A1', array['primeiros passos']::text[], null, 'a07ab63b', array['A verdade do vinho.', 'No vinho está a verdade.', 'No vinho, as verdades.', 'O vinho é a verdade.', 'Para o vinho, a verdade.']::text[]),
  ('la-pt', 'la-f028', 'frase', 'A1', array['primeiros passos']::text[], null, 'b3e07c46', array['No princípio era o Verbo.', 'No princípio será o Verbo.', 'No princípio é o Verbo.', 'O Verbo era o princípio.', 'O princípio era o Verbo.']::text[]),
  ('la-pt', 'la-f031', 'frase', 'A1', array['primeiros passos']::text[], null, '3e308208', array['A mente cura o corpo.', 'A mente sã de um corpo são.', 'Mente sã em corpo são.', 'Mentes sãs em corpos sãos.', 'Um corpo são numa mente sã.']::text[]),
  ('la-pt', 'la-f057', 'frase', 'A1', array['primeiros passos']::text[], null, '529f4052', array['A pátria está bem ali.', 'Onde estava bem, ali era a pátria.', 'Onde está a pátria, aí está o bem.', 'Onde há bem, há pátrias.', 'Onde se está bem, aí está a pátria.']::text[]),
  ('la-pt', 'la-f058', 'frase', 'A1', array['primeiros passos']::text[], null, '62240ee9', array['Ensinam os homens enquanto aprendem.', 'O homem, enquanto ensina, aprende.', 'Os homens ensinavam e aprendiam.', 'Os homens, enquanto aprendem, ensinam.', 'Os homens, enquanto ensinam, aprendem.']::text[]),
  ('la-pt', 'la-f032', 'frase', 'A1', array['primeiros passos']::text[], null, '8afcfd1d', array['Eu sigo quem não anda nas trevas.', 'Quem eu sigo não anda nas trevas.', 'Quem me segue anda nas trevas.', 'Quem me segue não anda nas trevas.', 'Quem me seguiu não anda nas trevas.']::text[]),
  ('la-pt', 'la-f033', 'frase', 'A1', array['primeiros passos']::text[], null, '24b6a0ce', array['A luz faz.', 'A luz foi feita.', 'Farei a luz.', 'Faça-se a luz.', 'Fez-se a luz.']::text[]),
  ('la-pt', 'la-f059', 'frase', 'A1', array['primeiros passos']::text[], null, '82e83221', array['Se a paz te quer, prepara a guerra.', 'Se queremos a paz, preparamos a guerra.', 'Se queres a guerra, prepara a paz.', 'Se queres a paz, prepara a guerra.', 'Se querias a paz, preparavas a guerra.']::text[]),
  ('la-pt', 'la-f034', 'frase', 'A1', array['primeiros passos']::text[], null, 'cac3ba54', array['A verdade nos libertará.', 'A verdade vos liberta.', 'A verdade vos libertará.', 'A verdade vos libertou.', 'Vós libertareis a verdade.']::text[]),
  ('la-pt', 'la-f036', 'frase', 'A1', array['primeiros passos']::text[], null, '7c252a8b', array['O Pai entrega o espírito em minhas mãos.', 'Pai, em tuas mãos entregaste o meu espírito.', 'Pai, em tuas mãos entrego o meu espírito.', 'Pai, em tuas mãos entrego o teu espírito.', 'Pai, entrega o meu espírito nas tuas mãos.']::text[]),
  ('la-pt', 'la-f037', 'frase', 'A1', array['primeiros passos']::text[], null, '75e24db3', array['Senhor, aonde foste?', 'Senhor, aonde irás?', 'Senhor, aonde vais?', 'Senhor, aonde vamos?', 'Senhor, de onde vens?']::text[]),
  ('la-pt', 'la-t001', 'frase', 'A1', array['trecho']::text[], null, '909c8d06', array['Glória ao Pai e ao Filho do Espírito Santo.', 'Glória ao Pai, ao Filho e ao Espírito Santo.', 'Glória aos pais, aos filhos e aos santos.', 'Glória do Pai, do Filho e do Espírito Santo.', 'O Pai, o Filho e o Espírito Santo dão glória.']::text[]),
  ('la-pt', 'la-t002', 'frase', 'A1', array['trecho']::text[], null, 'f0da6695', array['Como era no princípio, agora e sempre,', 'Como era no princípio, e não agora nem sempre,', 'Como era o princípio, agora e sempre,', 'Como será no princípio, agora e sempre,', 'Como é no princípio, agora e sempre,']::text[]),
  ('la-pt', 'la-t003', 'frase', 'A1', array['trecho']::text[], null, 'bcb50b4f', array['e no século dos séculos. Amém.', 'e nos séculos passados. Amém.', 'e para os santos dos séculos. Amém.', 'e pelos séculos do século. Amém.', 'e pelos séculos dos séculos. Amém.']::text[]),
  ('la-pt', 'la-t004', 'frase', 'A1', array['trecho']::text[], null, '77c7508e', array['O Pai nosso está nos céus,', 'Pai dos nossos, que estás nos céus,', 'Pai nosso, que estavas nos céus,', 'Pai nosso, que estás nos céus,', 'Pai nosso, que vais aos céus,']::text[]),
  ('la-pt', 'la-t005', 'frase', 'A1', array['trecho']::text[], null, '44f1025c', array['o teu nome santifica.', 'santifica o teu nome.', 'santificado foi o teu nome.', 'santificado seja o teu nome.', 'santificaste o teu nome.']::text[]),
  ('la-pt', 'la-t006', 'frase', 'A1', array['trecho']::text[], null, '6367453f', array['O teu reino virá.', 'Veio o teu reino.', 'Vem ao teu reino.', 'Venha o teu reino.', 'Venham os teus reinos.']::text[]),
  ('la-pt', 'la-t007', 'frase', 'A1', array['trecho']::text[], null, '491d62ad', array['A tua vontade fará o céu e a terra.', 'Faze a tua vontade, assim na terra como no céu.', 'Foi feita a tua vontade, assim na terra como no céu.', 'Seja feita a tua vontade, assim na terra como no céu.', 'Seja feita a vontade do céu e da terra.']::text[]),
  ('la-pt', 'la-t008', 'frase', 'A1', array['trecho']::text[], null, 'ff77019b', array['Dá-nos hoje o pão de cada um,', 'O pão de cada dia é nosso hoje,', 'O pão nosso de cada dia damos hoje,', 'O pão nosso de cada dia dá-nos hoje,', 'O pão nosso de cada dia nos deste hoje,']::text[]),
  ('la-pt', 'la-t009', 'frase', 'A1', array['trecho']::text[], null, '106223a8', array['e nos perdoaste as nossas dívidas,', 'e perdoa as dívidas que nos deves,', 'e perdoa-nos a nossa dívida,', 'e perdoa-nos as nossas dívidas,', 'e perdoamos as nossas dívidas,']::text[]),
  ('la-pt', 'la-t010', 'frase', 'A1', array['trecho']::text[], null, '2966c143', array['assim como nós devemos aos nossos devedores.', 'assim como nós perdoamos aos nossos devedores.', 'assim como nós perdoávamos aos nossos devedores.', 'assim como os nossos devedores nos perdoam.', 'assim como vós perdoais aos vossos devedores.']::text[]),
  ('la-pt', 'la-t011', 'frase', 'A1', array['trecho']::text[], null, '94ac2d46', array['E não induzas a tentação,', 'E não nos induzas à tentação,', 'E não nos induzirás à tentação,', 'E não nos induziste à tentação,', 'E nós não te induzimos à tentação,']::text[]),
  ('la-pt', 'la-t012', 'frase', 'A1', array['trecho']::text[], null, '675522c9', array['mas livra-nos do mal. Amém.', 'mas livra-nos para o mal. Amém.', 'mas livramo-nos do mal. Amém.', 'mas livrou-nos do mal. Amém.', 'mas o mal nos livra. Amém.']::text[]),
  ('la-pt', 'la-t013', 'frase', 'A1', array['trecho']::text[], null, 'e8d352c7', array['Ave, Maria, a graça te enche,', 'Ave, Maria, cheia da graça de Deus,', 'Ave, Maria, cheia de graça,', 'Ave, Maria, cheia de graças,', 'Ave, Maria, graça cheia,']::text[]),
  ('la-pt', 'la-t014', 'frase', 'A1', array['trecho']::text[], null, 'debc23a2', array['O Senhor estava contigo.', 'O Senhor está comigo.', 'O Senhor é contigo.', 'O Senhor é teu.', 'Tu és o Senhor.']::text[]),
  ('la-pt', 'la-t015', 'frase', 'A1', array['trecho']::text[], null, '2d75b01d', array['abençoas tu as mulheres,', 'bendita tu és para as mulheres,', 'bendita és tu entre as mulheres,', 'bendita és tu por uma mulher,', 'benditas são as mulheres em ti,']::text[]),
  ('la-pt', 'la-t016', 'frase', 'A1', array['trecho']::text[], null, '95871aa0', array['e Jesus bendiz o fruto do teu ventre.', 'e bendito é o fruto do teu ventre, Jesus.', 'e bendito é o teu ventre, fruto de Jesus.', 'e bendito é o ventre do teu fruto, Jesus.', 'e benditos são os frutos do teu ventre, Jesus.']::text[]),
  ('la-pt', 'la-t017', 'frase', 'A1', array['trecho']::text[], null, '7ed0c186', array['Santa Maria e a Mãe de Deus,', 'Santa Maria, Mãe de Deus,', 'Santa Maria, Mãe dos deuses,', 'Santa Maria, Mãe para Deus,', 'Santa Maria, a Mãe é de Deus,']::text[]),
  ('la-pt', 'la-t018', 'frase', 'A1', array['trecho']::text[], null, '964f5e71', array['roga conosco, pecadores,', 'roga pelos pecadores e por nós,', 'roga por nós, pecadores,', 'rogamos por vós, pecadores,', 'rogou por nós, pecadores,']::text[]),
  ('la-pt', 'la-t019', 'frase', 'A1', array['trecho']::text[], null, '01f238a3', array['agora e na hora da nossa morte. Amém.', 'agora e na hora da vossa morte. Amém.', 'agora e na hora para a nossa morte. Amém.', 'agora e na morte da nossa hora. Amém.', 'agora e nas horas da nossa morte. Amém.']::text[]),
  ('la-pt', 'la-t020', 'frase', 'A1', array['trecho']::text[], null, 'd030b3c1', array['Não amo Sabídio, e ele não pode dizer por quê:', 'Não me amas, Sabídio, e não podes dizer por quê:', 'Não te amei, Sabídio, e não pude dizer por quê:', 'Não te amo, Sabídio, e não posso dizer por quê:', 'Não te amo, Sabídio, mas posso dizer por quê:']::text[]),
  ('la-pt', 'la-t021', 'frase', 'A1', array['trecho']::text[], null, 'a668eb26', array['isto não posso dizer: não te amo.', 'só isto podes dizer: não te amo.', 'só isto posso dizer: não te amo.', 'só isto pude dizer: não te amei.', 'tanto posso dizer que te amo.']::text[]),
  ('la-pt', 'la-u001', 'frase', 'A1', array['frase de uso']::text[], 'la-p001', 'dcf71a45', array['Nós somos os vossos deuses.', 'Os nossos deuses estão convosco.', 'Vós sois o nosso Deus.', 'Vós sois os nossos deuses.', 'Vós éreis os nossos deuses.']::text[]),
  ('la-pt', 'la-u002', 'frase', 'A1', array['frase de uso']::text[], 'la-p002', 'ad232ecb', array['Não haverá temor no amor.', 'Não havia temor no amor.', 'Não há amor no temor.', 'Não há temor no amor.', 'O temor não é o amor.']::text[]),
  ('la-pt', 'la-u003', 'frase', 'A1', array['frase de uso']::text[], 'la-p003', '87b848e8', array['Eu e o Pai seremos um.', 'Eu e o Pai somos um.', 'Eu e o Pai éramos um.', 'Eu e os pais somos um.', 'Tu e o Pai sois um.']::text[]),
  ('la-pt', 'la-u005', 'frase', 'A1', array['frase de uso']::text[], 'la-p005', '60883df6', array['e eu não me perturbarei, seguindo-te como pastor.', 'e eu não me perturbei, seguindo-te como pastor.', 'e eu não perturbei o pastor que te segue.', 'e o pastor não se perturbou, seguindo-te.', 'e tu não te perturbaste, seguindo-me como pastor.']::text[]),
  ('la-pt', 'la-u006', 'frase', 'A1', array['frase de uso']::text[], 'la-p006', '6053fe32', array['O caminho do bem é teu.', 'O teu caminho era bom.', 'O teu caminho é bom.', 'Os teus caminhos são bons.', 'Tu és o bom caminho.']::text[]),
  ('la-pt', 'la-u007', 'frase', 'A1', array['frase de uso']::text[], 'la-p007', 'ebca4fc3', array['Ide, e o Senhor esteja convosco.', 'Vai, e o Senhor esteja comigo.', 'Vai, e o Senhor esteja contigo.', 'Vai, e o Senhor está contigo.', 'Vou, e o Senhor esteja contigo.']::text[]),
  ('la-pt', 'la-u009', 'frase', 'A1', array['frase de uso']::text[], 'la-p009', '93fdb4a7', array['Luz e trevas bendisseram o Senhor.', 'Luz e trevas bendizem o Senhor.', 'Luz e trevas, bendizei o Senhor.', 'O Senhor bendiz luz e trevas.', 'Senhor, bendize a luz e as trevas.']::text[]),
  ('la-pt', 'la-u010', 'frase', 'A1', array['frase de uso']::text[], 'la-p010', '60c3c253', array['a paz é a verdade dos meus dias.', 'haja paz e verdade nos meus dias.', 'haja paz e verdade nos teus dias.', 'houve paz e verdade nos meus dias.', 'há paz e verdade nos meus dias.']::text[]),
  ('la-pt', 'la-u011', 'frase', 'A1', array['frase de uso']::text[], 'la-p011', 'cfb1c7ad', array['Louvai o Senhor em vossa vida.', 'Louvarei o Senhor da minha vida.', 'Louvarei o Senhor em minha vida.', 'Louvei o Senhor em minha vida.', 'O Senhor louvará a minha vida.']::text[]),
  ('la-pt', 'la-u013', 'frase', 'A1', array['frase de uso']::text[], 'la-p013', 'd457eb38', array['Não sou teu senhor.', 'Não és meu senhor.', 'Não, meu senhor.', 'Não, meus senhores.', 'Senhor, eu não.']::text[]),
  ('la-pt', 'la-u015', 'frase', 'A1', array['frase de uso']::text[], 'la-p015', 'bbecbfca', array['todos os filhos dos homens o viram.', 'viu o filho de todos os homens.', 'viu todos os filhos dos homens.', 'viu todos os homens dos filhos.', 'vê todos os filhos dos homens.']::text[]),
  ('la-pt', 'la-u016', 'frase', 'A1', array['frase de uso']::text[], 'la-p016', 'cdbdee0d', array['A glória do Senhor é grande.', 'A grande glória segue o Senhor.', 'Era grande glória seguir o Senhor.', 'É grande glória o Senhor nos seguir.', 'É grande glória seguir o Senhor.']::text[]),
  ('la-pt', 'la-u019', 'frase', 'A1', array['frase de uso']::text[], 'la-p019', '4ce65bd0', array['A graça de todos vós.', 'A graça esteja com todos nós.', 'A graça esteja com todos vós.', 'A graça esteve com todos vós.', 'Todos vós estais na graça.']::text[]),
  ('la-pt', 'la-u020', 'frase', 'A1', array['frase de uso']::text[], 'la-p020', '0e7a1e5d', array['E anunciaram a minha glória às nações.', 'E anunciarei a minha glória às nações.', 'E anunciarão a glória das nações.', 'E anunciarão a minha glória às nações.', 'E as nações anunciarão a minha glória.']::text[]),
  ('la-pt', 'la-u023', 'frase', 'A1', array['frase de uso']::text[], 'la-p023', 'b7cc3dff', array['Deus é bom para um só.', 'Só os deuses são bons.', 'Um só era bom: Deus.', 'Um só será bom: Deus.', 'Um só é bom: Deus.']::text[]),
  ('la-pt', 'la-u027', 'frase', 'A1', array['frase de uso']::text[], 'la-p027', '5d8334d8', array['Sois todos filhos de um só homem.', 'Somos filhos de todos os homens.', 'Somos todos filhos de um só homem.', 'Somos todos homens de um só filho.', 'Éramos todos filhos de um só homem.']::text[]),
  ('la-pt', 'la-u028', 'frase', 'A1', array['frase de uso']::text[], 'la-p028', '7be95628', array['E Deus andou com ele, e não apareceu.', 'E anda com Deus, e não aparece.', 'E andaram com Deus, e não apareceram.', 'E andei com Deus, e não apareci.', 'E andou com Deus, e não apareceu.']::text[]),
  ('la-pt', 'la-u029', 'frase', 'A1', array['frase de uso']::text[], 'la-p029', '651d2e97', array['Cantamos convosco, e não dançastes.', 'Cantamos para vós, e não dançamos.', 'Cantamos para vós, e não dançastes.', 'Cantaremos para vós, e não dançareis.', 'Cantastes para nós, e não dançamos.']::text[]),
  ('la-pt', 'la-u032', 'frase', 'A1', array['frase de uso']::text[], 'la-p032', 'cbdce7d3', array['Ele toma o que é teu, e vai.', 'Toma o que foi teu, e vai.', 'Toma o que é meu, e vai.', 'Toma o que é teu, e vai.', 'Tomai o que é vosso, e ide.']::text[]),
  ('la-pt', 'la-u033', 'frase', 'A1', array['frase de uso']::text[], 'la-p033', '1613ed19', array['a lei não vos leu?', 'não lemos a lei?', 'não lereis a lei?', 'não lestes a lei?', 'não lês a lei?']::text[]),
  ('la-pt', 'la-u034', 'frase', 'A1', array['frase de uso']::text[], 'la-p034', '1cd67e3a', array['não te tornes escravo dos homens.', 'não vos tornastes escravos dos homens.', 'não vos torneis escravos do homem.', 'não vos torneis escravos dos homens.', 'os homens não querem ser escravos.']::text[]),
  ('la-pt', 'la-u035', 'frase', 'A1', array['frase de uso']::text[], 'la-p035', 'effbcf8b', array['Quem é que eu toquei?', 'Quem é que me toca?', 'Quem é que me tocou?', 'Quem é que nos tocou?', 'Quem é que te tocou?']::text[]),
  ('la-pt', 'la-u038', 'frase', 'A1', array['frase de uso']::text[], 'la-p038', 'c4949439', array['Vem e vê.', 'Venho e vejo.', 'Viemos e vimos.', 'Vieram e viram.', 'Vinde e vede.']::text[]),
  ('la-pt', 'la-u039', 'frase', 'A1', array['frase de uso']::text[], 'la-p039', 'd61d197a', array['E os filhos dos teus filhos te vejam.', 'E vejas os filhos do teu filho.', 'E vejas os filhos dos teus filhos.', 'E vejo os filhos dos teus filhos.', 'E viste os filhos dos teus filhos.']::text[]),
  ('la-pt', 'la-u041', 'frase', 'A1', array['frase de uso']::text[], 'la-p041', 'b9a6c42c', array['O Senhor era a minha luz.', 'O Senhor é a minha luz.', 'O Senhor é a tua luz.', 'O meu Senhor é a luz.', 'Os senhores são a minha luz.']::text[]),
  ('la-pt', 'la-u042', 'frase', 'A1', array['frase de uso']::text[], 'la-p042', '5fb59f71', array['Nós somos a luz do mundo.', 'Vós sois a luz do mundo.', 'Vós sois a luz para o mundo.', 'Vós sois as luzes do mundo.', 'Vós éreis a luz do mundo.']::text[]),
  ('la-pt', 'la-u043', 'frase', 'A1', array['frase de uso']::text[], 'la-p043', '6cdf73e5', array['O Filho de Deus crê em ti?', 'Tu creste no Filho de Deus?', 'Tu crês no Deus do Filho?', 'Tu crês no Filho de Deus?', 'Vós credes no Filho de Deus?']::text[]),
  ('la-pt', 'la-u048', 'frase', 'A1', array['frase de uso']::text[], 'la-p048', 'b0efb747', array['e a paz de Deus estará convosco.', 'e o Deus da paz estará conosco.', 'e o Deus da paz estará convosco.', 'e o Deus da paz está convosco.', 'e o Deus estará em paz convosco.']::text[]),
  ('la-pt', 'la-u049', 'frase', 'A1', array['frase de uso']::text[], 'la-p049', '5a07f4ed', array['O Senhor esteja com todos nós.', 'O Senhor esteja com todos vós.', 'O Senhor esteve com todos vós.', 'O Senhor está com todos vós.', 'O Senhor seja de todos vós.']::text[]),
  ('la-pt', 'la-u050', 'frase', 'A1', array['frase de uso']::text[], 'la-p050', '1a50b6ff', array['Graça a nós, e paz.', 'Graça a ti, e paz.', 'Graça a vós, e paz.', 'Graça vinda de vós, e paz.', 'Vós sois graça e paz.']::text[]),
  ('la-pt', 'la-u051', 'frase', 'A1', array['frase de uso']::text[], 'la-p051', '2c51df27', array['e vieram, e viram a minha glória.', 'e virei, e verei a minha glória.', 'e virão, e a minha glória os verá.', 'e virão, e verão a minha glória.', 'e virão, e verão a tua glória.']::text[]),
  ('la-pt', 'la-u052', 'frase', 'A1', array['frase de uso']::text[], 'la-p052', '778ccce7', array['Sois deuses, e todos filhos do Altíssimo.', 'Sois os deuses dos filhos do Altíssimo.', 'Somos deuses, e todos filhos do Altíssimo.', 'Éreis deuses, e todos filhos do Altíssimo.', 'És deus, e filho do Altíssimo.']::text[]),
  ('la-pt', 'la-u053', 'frase', 'A1', array['frase de uso']::text[], 'la-p053', '6596e4d4', array['Eu estarei contigo.', 'Eu estarei convosco.', 'Eu estava contigo.', 'Eu estou contigo.', 'Tu estarás comigo.']::text[]),
  ('la-pt', 'la-u054', 'frase', 'A1', array['frase de uso']::text[], 'la-p054', 'd7cc5afa', array['O Senhor louve todo espírito!', 'Todo espírito louva o Senhor!', 'Todo espírito louve o Senhor!', 'Todo espírito louvou o Senhor!', 'Todos os espíritos louvem o Senhor!']::text[]),
  ('la-pt', 'la-u056', 'frase', 'A1', array['frase de uso']::text[], 'la-p056', '336501ac', array['A tua palavra é o princípio da verdade.', 'O princípio da tua palavra é a verdade.', 'O princípio das minhas palavras é a verdade.', 'O princípio das tuas palavras era a verdade.', 'O princípio das tuas palavras é a verdade.']::text[]),
  ('la-pt', 'la-u057', 'frase', 'A1', array['frase de uso']::text[], 'la-p057', 'da14d49c', array['e não creias em nenhuma palavra.', 'e não creias em toda palavra.', 'e não cremos em toda palavra.', 'e não creste em toda palavra.', 'e não crês em toda palavra.']::text[]),
  ('la-pt', 'la-u061', 'frase', 'A1', array['frase de uso']::text[], 'la-p061', 'd4691413', array['Orai com o espírito, orai também com a mente.', 'Orarei ao espírito, e orarei também à mente.', 'Orarei com o espírito, orarei também com a mente.', 'Orarás com o espírito, orarás também com a mente.', 'Orei com o espírito, orei também com a mente.']::text[]),
  ('la-pt', 'la-u062', 'frase', 'A1', array['frase de uso']::text[], 'la-p062', '8079b618', array['Quereis ficar sãos?', 'Queres fazer-me são?', 'Queres ficar são?', 'Querias ficar são?', 'Quero ficar são.']::text[]),
  ('la-pt', 'la-u063', 'frase', 'A1', array['frase de uso']::text[], 'la-p063', 'af4a96d7', array['E o Senhor está no corpo.', 'E o Senhor é o corpo.', 'E o Senhor é para o corpo.', 'E o corpo é para o Senhor.', 'E é o corpo do Senhor.']::text[]),
  ('la-pt', 'la-u064', 'frase', 'A1', array['frase de uso']::text[], 'la-p064', 'f25b7aad', array['e o que era de Deus, a Deus.', 'e o que é de Deus, a Deus.', 'e o que é de Deus, com Deus.', 'e o que é para Deus, de Deus.', 'e quem é de Deus, a Deus.']::text[]),
  ('la-pt', 'la-u065', 'frase', 'A1', array['frase de uso']::text[], 'la-p065', '020c5868', array['Ele me segue.', 'Eu te sigo.', 'Tu me seguias.', 'Tu me seguiste.', 'Tu, segue-me.']::text[]),
  ('la-pt', 'la-u066', 'frase', 'A1', array['frase de uso']::text[], 'la-p066', 'd0d3ff06', array['Paz, e não haverá paz.', 'Paz, e não havia paz.', 'Paz, e não houve paz.', 'Paz, e não há paz.', 'Paz, e que não haja paz.']::text[]),
  ('la-pt', 'la-u067', 'frase', 'A1', array['frase de uso']::text[], 'la-p067', 'ab30b46b', array['Anda com Deus.', 'Andaram com Deus.', 'Andará com Deus.', 'Andou com Deus.', 'Deus andou com ele.']::text[]),
  ('la-pt', 'la-u068', 'frase', 'A1', array['frase de uso']::text[], 'la-p068', '828c292d', array['Anda nas trevas.', 'Andam nas trevas.', 'Andam para as trevas.', 'Andaram nas trevas.', 'Andarão nas trevas.']::text[]),
  ('la-pt', 'la-u069', 'frase', 'A1', array['frase de uso']::text[], 'la-p069', '3d9936cf', array['Que a caridade faça tudo o que é vosso.', 'Que tudo o que é nosso se faça na caridade.', 'Que tudo o que é vosso se faça na caridade.', 'Tudo o que é vosso se fará na caridade.', 'Tudo o que é vosso se fez na caridade.']::text[]),
  ('la-pt', 'la-u070', 'frase', 'A1', array['frase de uso']::text[], 'la-p070', 'ab26743f', array['Nós libertaremos o Senhor.', 'O Senhor nos liberta.', 'O Senhor nos libertará.', 'O Senhor nos libertou.', 'O Senhor vos libertará.']::text[]),
  ('la-pt', 'la-u072', 'frase', 'A1', array['frase de uso']::text[], 'la-p072', '66bbc377', array['Onde estava o teu Pai?', 'Onde está o meu Pai?', 'Onde está o teu Pai?', 'Onde estás, ó Pai?', 'Onde estão os teus pais?']::text[]),
  ('la-pt', 'la-u076', 'frase', 'A1', array['frase de uso']::text[], 'la-p076', '325c6308', array['Ele vai em paz.', 'Foste em paz.', 'Vai em paz.', 'Vamos em paz.', 'Vou em paz.']::text[]),
  ('la-pt', 'la-u077', 'frase', 'A1', array['frase de uso']::text[], 'la-p077', '69f9256b', array['Ora por nós.', 'Orai conosco.', 'Orai por nós.', 'Oramos por vós.', 'Oraram por nós.']::text[]),
  ('la-pt', 'la-u078', 'frase', 'A1', array['frase de uso']::text[], 'la-p078', 'a2fd4853', array['O Senhor nosso Deus roga por nós.', 'Roga conosco ao Senhor nosso Deus.', 'Roga por nós ao Senhor, nosso Deus.', 'Roga por nós, Senhor nosso Deus.', 'Rogou por nós ao Senhor nosso Deus.']::text[]),
  ('la-pt', 'la-u079', 'frase', 'A1', array['frase de uso']::text[], 'la-p079', '31d20497', array['Eles também vão contigo.', 'Nós também vamos contigo.', 'Nós também íamos contigo.', 'Tu também vais conosco.', 'Vós também ides conosco.']::text[]),
  ('la-pt', 'la-u082', 'frase', 'A1', array['frase de uso']::text[], 'la-p082', '878455f8', array['Aonde vai o teu Deus?', 'Onde estará o teu Deus?', 'Onde estava o teu Deus?', 'Onde está o teu Deus?', 'Onde estás, ó Deus?']::text[]),
  ('la-pt', 'la-u083', 'frase', 'A1', array['frase de uso']::text[], 'la-p083', '4a6ce54d', array['Lá eu os verei.', 'Lá me veem.', 'Lá me verás.', 'Lá me verão.', 'Lá me viram.']::text[]),
  ('la-pt', 'la-u084', 'frase', 'A1', array['frase de uso']::text[], 'la-p084', 'f86e8920', array['Os homens santos serão para mim.', 'Sereis para mim homens santos.', 'Seremos para ti homens santos.', 'Sois para mim homens santos.', 'Éreis para mim homens santos.']::text[]),
  ('la-pt', 'la-u085', 'frase', 'A1', array['frase de uso']::text[], 'la-p085', 'e9b3a7e0', array['Nosso Deus é como um grande deus.', 'Que deus era grande como o nosso Deus?', 'Que deus é grande como o nosso Deus?', 'Que deus é grande como os nossos deuses?', 'Que deus é maior que o nosso Deus?']::text[]),
  ('la-pt', 'la-u086', 'frase', 'A1', array['frase de uso']::text[], 'la-p086', '89b95afb', array['Agora eu amarei o meu marido.', 'Agora o meu marido me ama.', 'Agora o meu marido me amará.', 'Agora o meu marido me amava.', 'Agora o meu marido me amou.']::text[]),
  ('la-pt', 'la-u087', 'frase', 'A1', array['frase de uso']::text[], 'la-p087', '348a5843', array['Alegrai sempre o Senhor.', 'Alegrai-vos agora no Senhor.', 'Alegrai-vos sempre no Senhor.', 'O Senhor se alegra sempre.', 'Vós vos alegrastes sempre no Senhor.']::text[]),
  ('la-pt', 'la-u089', 'frase', 'A1', array['frase de uso']::text[], 'la-p089', '5baae445', array['Bendisseram o Senhor, nosso Deus.', 'Bendizei o Senhor do nosso Deus.', 'Bendizei o Senhor, nosso Deus.', 'Bendizemos o Senhor, nosso Deus.', 'O Senhor, nosso Deus, vos bendiz.']::text[]),
  ('la-pt', 'la-u090', 'frase', 'A1', array['frase de uso']::text[], 'la-p090', '715d9ce0', array['O Senhor é o céu do céu.', 'O céu do Senhor é do céu.', 'O céu do céu era do Senhor.', 'O céu do céu está com o Senhor.', 'O céu do céu é do Senhor.']::text[]),
  ('la-pt', 'la-u091', 'frase', 'A1', array['frase de uso']::text[], 'la-p091', '44224d25', array['Eu sou o Senhor, que me santificais.', 'Eu sou o Senhor, que vos santificarei.', 'Eu sou o Senhor, que vos santifico.', 'Eu sou o Senhor, que vos santifiquei.', 'Sou o Senhor, santificado por vós.']::text[]),
  ('la-pt', 'la-u092', 'frase', 'A1', array['frase de uso']::text[], 'la-p092', 'f80c7265', array['Louvai em nome do Senhor.', 'Louvai o nome do Senhor.', 'Louvamos o nome do Senhor.', 'Louvaram o nome do Senhor.', 'O nome do Senhor vos louva.']::text[]),
  ('la-pt', 'la-u094', 'frase', 'A1', array['frase de uso']::text[], 'la-p094', 'e26cf935', array['Não estarás longe do reino de Deus.', 'Não estavas longe do reino de Deus.', 'Não estou longe do reino de Deus.', 'Não estás longe do reino de Deus.', 'O reino de Deus não está longe.']::text[]),
  ('la-pt', 'la-u095', 'frase', 'A1', array['frase de uso']::text[], 'la-p095', 'a90a10a7', array['Faze a vontade do Senhor.', 'Faça-se a vontade do Senhor.', 'Foi feita a vontade do Senhor.', 'O Senhor fez a sua vontade.', 'Será feita a vontade do Senhor.']::text[]),
  ('la-pt', 'la-u096', 'frase', 'A1', array['frase de uso']::text[], 'la-p096', '30e830e5', array['Meus são os céus, e minha é a terra.', 'Teus eram os céus, e tua era a terra.', 'Teus serão os céus, e tua será a terra.', 'Teus são os céus, e tua é a terra.', 'Tu estás nos céus e na terra.']::text[]),
  ('la-pt', 'la-u097', 'frase', 'A1', array['frase de uso']::text[], 'la-p097', 'f79b9b10', array['Eu era o pão da vida.', 'Eu sou a vida do pão.', 'Eu sou o pão da vida.', 'Eu sou o pão e a vida.', 'Eu sou o pão para a vida.']::text[]),
  ('la-pt', 'la-u099', 'frase', 'A1', array['frase de uso']::text[], 'la-p099', '6e3c85df', array['Dai, e nos será dado.', 'Dai, e vos foi dado.', 'Dai, e vos será dado.', 'Dai, e vós dareis.', 'Dão, e vos é dado.']::text[]),
  ('la-pt', 'la-u100', 'frase', 'A1', array['frase de uso']::text[], 'la-p100', '061e276c', array['Hoje estarei contigo no paraíso.', 'Hoje estarás comigo no paraíso.', 'Hoje estavas comigo no paraíso.', 'Hoje estiveste comigo no paraíso.', 'Hoje estás comigo no paraíso.']::text[]),
  ('la-pt', 'la-u101', 'frase', 'A1', array['frase de uso']::text[], 'la-p101', 'f3459d16', array['Levanta-te, e eu te despedi.', 'Levanta-te, e eu te despedirei.', 'Levanta-te, e eu te despeço.', 'Levanta-te, e tu me despedirás.', 'Levantai-vos, e eu vos despedirei.']::text[]),
  ('la-pt', 'la-u103', 'frase', 'A1', array['frase de uso']::text[], 'la-p103', '588eae5a', array['e eram devedores deles.', 'e os devedores são deles.', 'e serão devedores deles.', 'e somos devedores deles.', 'e são devedores deles.']::text[]),
  ('la-pt', 'la-u104', 'frase', 'A1', array['frase de uso']::text[], 'la-p104', 'e4ff0098', array['Pedes-me que não te esconda nada.', 'Pedi-te que não me escondesses nada.', 'Peço-te que me escondas tudo.', 'Peço-te que não me escondas nada.', 'Peço-te: não me escondeste nada.']::text[]),
  ('la-pt', 'la-u105', 'frase', 'A1', array['frase de uso']::text[], 'la-p105', '5509916d', array['Não nos leves para a armadilha.', 'Nós te levamos para a armadilha.', 'Tu nos levarás para a armadilha.', 'Tu nos levas para a armadilha.', 'Tu nos levaste para a armadilha.']::text[]),
  ('la-pt', 'la-u106', 'frase', 'A1', array['frase de uso']::text[], 'la-p106', '527bfa15', array['Orai para entrardes em tentação.', 'Orai para não entrardes em tentação.', 'Orai, e não entrareis em tentação.', 'Oramos para não entrar em tentação.', 'Orou para não entrar em tentação.']::text[]),
  ('la-pt', 'la-u107', 'frase', 'A1', array['frase de uso']::text[], 'la-p107', '0f37c856', array['e as mãos são as mãos de Esaú.', 'mas a mão é a mão de Esaú.', 'mas as mãos eram as mãos de Esaú.', 'mas as mãos serão as mãos de Esaú.', 'mas as mãos são as mãos de Esaú.']::text[]),
  ('la-pt', 'la-u108', 'frase', 'A1', array['frase de uso']::text[], 'la-p108', '2a78403c', array['Não deixes de vencer o mal, mas vence o mal com o bem.', 'Não te deixaste vencer pelo mal, mas venceste o mal com o bem.', 'Não te deixes vencer pelo bem, mas vence o bem com o mal.', 'Não te deixes vencer pelo mal, mas vence o mal com o bem.', 'Não te deixes vencer: afasta-te do mal e vence o mal com o bem.']::text[]),
  ('la-pt', 'la-u112', 'frase', 'A1', array['frase de uso']::text[], 'la-p112', '59f0959c', array['Deus nos abençoa, o nosso Deus!', 'Deus nos abençoou, o nosso Deus!', 'Que Deus nos abençoe, o nosso Deus!', 'Que Deus vos abençoe, o vosso Deus!', 'Que nós bendigamos a Deus, o nosso Deus!']::text[]),
  ('la-pt', 'la-u115', 'frase', 'A1', array['frase de uso']::text[], 'la-p115', '32148d2d', array['Desde o ventre de minha mãe, eu sou o teu Deus.', 'Desde o ventre de minha mãe, tu eras o meu Deus.', 'Desde o ventre de minha mãe, tu serás o meu Deus.', 'Desde o ventre de minha mãe, tu és o meu Deus.', 'Desde o ventre de tua mãe, tu és o meu Deus.']::text[]),
  ('la-pt', 'la-u117', 'frase', 'A1', array['frase de uso']::text[], 'la-p117', '5fcb37fe', array['Deus foi propício a mim, pecador.', 'Deus é propício a mim, pecador.', 'Ó Deus, eras propício a mim, pecador.', 'Ó Deus, sê propício a mim, pecador.', 'Ó Deus, sê propício a nós, pecadores.']::text[]),
  ('la-pt', 'la-u118', 'frase', 'A1', array['frase de uso']::text[], 'la-p118', 'ae4615f9', array['A hora do Pai chegou.', 'O Pai chegou na hora.', 'Pai, chegará a hora.', 'Pai, chegava a hora.', 'Pai, chegou a hora.']::text[]),
  ('la-pt', 'la-u119', 'frase', 'A1', array['frase de uso']::text[], 'la-p119', 'a45674ac', array['Onde estará, ó morte, a tua vitória?', 'Onde estava, ó morte, a tua vitória?', 'Onde está a vitória da morte?', 'Onde está, ó morte, a minha vitória?', 'Onde está, ó morte, a tua vitória?']::text[]),
  ('la-pt', 'la-u120', 'frase', 'A1', array['frase de uso']::text[], 'la-p120', '9bbe5b2d', array['E o Senhor estará convosco.', 'E o Senhor não estará conosco.', 'E o Senhor não estará convosco.', 'E o Senhor não estava convosco.', 'E o Senhor não está convosco.']::text[]),
  ('la-pt', 'la-u121', 'frase', 'A1', array['frase de uso']::text[], 'la-p121', '1dd55471', array['Para onde eu ia, vós não podíeis ir.', 'Para onde eu vou, vós não podeis ir.', 'Para onde eu vou, vós não podereis ir.', 'Para onde eu vou, vós não pudestes ir.', 'Para onde vós ides, eu não posso ir.']::text[]),
  ('la-pt', 'la-u122', 'frase', 'A1', array['frase de uso']::text[], 'la-p122', 'cf047cbd', array['Eu estou convosco, digo ao Senhor.', 'Eu estou convosco, disse o Senhor.', 'Eu estou convosco, diz o Senhor.', 'Eu estou convosco, dizem os senhores.', 'Vós estais comigo, diz o Senhor.']::text[]),
