  ('la-pt', 'la-p207', 'palavra', 'A1', array['substantivo', '4ª declinação']::text[], null, '1c3e77df', array['a haste', 'a hóstia', 'o gole', 'o hábito', 'o hálito']::text[]),
  ('la-pt', 'la-p208', 'palavra', 'A1', array['substantivo', '3ª declinação']::text[], null, '88aea6d8', array['a liga (a mistura)', 'o limo (o lodo)', 'o lixo (a sujeira)', 'o lucro (o ganho)', 'o líquido (a água)']::text[]),
  ('la-pt', 'la-t022', 'frase', 'A1', array['trecho']::text[], null, '89e523a6', array['Odeias e amas. Por que fazes isso, talvez eu pergunte.', 'Odeio e amo. Por que fazes isso, talvez eu pergunte.', 'Odeio e amo. Por que faço isso, talvez perguntes.', 'Odeio o amor. Por que faço isso, talvez perguntes.', 'Odiei e amei. Por que fiz isso, talvez perguntes.']::text[]),
  ('la-pt', 'la-t023', 'frase', 'A1', array['trecho']::text[], null, '03daa3fc', array['Não sabes, mas sentes que acontece e te torturas.', 'Não sabia, mas sentia que acontecia e me torturava.', 'Não sei, mas sinto que acontece e me torturo.', 'Não sei, mas sinto que faço e torturo.', 'Sei, mas não sinto que acontece e me torturo.']::text[]),
  ('la-pt', 'la-t024', 'frase', 'A1', array['trecho']::text[], null, 'f14f027f', array['A rainha do céu se alegrou, aleluia.', 'Rainha do céu, alegra-te, aleluia.', 'Rainha, alegra o céu, aleluia.', 'Rainha, o céu se alegra, aleluia.', 'Rainhas do céu, alegrai-vos, aleluia.']::text[]),
  ('la-pt', 'la-t025', 'frase', 'A1', array['trecho']::text[], null, '129d7829', array['Porque aquele que merecerás trazer, aleluia.', 'Porque aquele que mereces trazer, aleluia.', 'Porque aquele que mereceste trazer, aleluia.', 'Porque aquele que te mereceu trazer, aleluia.', 'Porque mereceu trazer aquele, aleluia.']::text[]),
  ('la-pt', 'la-t026', 'frase', 'A1', array['trecho']::text[], null, 'ac507ebe', array['Ressuscita, como diz, aleluia.', 'Ressuscitaram, como disseram, aleluia.', 'Ressuscitará, como disse, aleluia.', 'Ressuscitei, como disse, aleluia.', 'Ressuscitou, como disse, aleluia.']::text[]),
  ('la-pt', 'la-t027', 'frase', 'A1', array['trecho']::text[], null, 'c0e692c6', array['Deus roga por nós, aleluia.', 'Roga a Deus por nós, aleluia.', 'Roga a nós por Deus, aleluia.', 'Rogai a Deus por nós, aleluia.', 'Rogou a Deus por nós, aleluia.']::text[]),
  ('la-pt', 'la-t028', 'frase', 'A2', array['trecho']::text[], null, '2f6f1cd0', array['Ao mesmo riacho o lobo e o cordeiro tinham vindo,', 'Ao mesmo riacho o lobo e o cordeiro vêm,', 'Ao mesmo riacho o lobo tinha levado o cordeiro,', 'Ao mesmo riacho os lobos e os cordeiros tinham vindo,', 'O lobo e o cordeiro do mesmo riacho tinham vindo,']::text[]),
  ('la-pt', 'la-t029', 'frase', 'A2', array['trecho']::text[], null, '942b62c4', array['impelido pela sede, o lobo estava acima,', 'impelidos pela sede; mais acima estava o lobo,', 'impelidos pela sede; mais acima estavam os lobos,', 'impelidos pela sede; mais acima está o lobo,', 'impelindo a sede; mais acima estava o lobo,']::text[]),
  ('la-pt', 'la-t030', 'frase', 'A2', array['trecho']::text[], null, '4cc8e10c', array['e muito mais abaixo o cordeiro. Então, com a goela insaciável,', 'e muito mais abaixo o cordeiro. Então, com as goelas insaciáveis,', 'e muito mais abaixo o cordeiro. Então, da goela insaciável,', 'e muito mais abaixo os cordeiros. Então, com a goela insaciável,', 'e o cordeiro, longe do inferior. Então, a goela insaciável']::text[]),
  ('la-pt', 'la-t031', 'frase', 'A2', array['trecho']::text[], null, '5872a400', array['a briga do ladrão trouxe um motivo.', 'o ladrão incitou a causa da briga.', 'o ladrão, incitado, traz um motivo de briga.', 'o ladrão, incitado, trouxe um motivo de briga.', 'os ladrões, incitados, trouxeram um motivo de briga.']::text[]),
  ('la-pt', 'la-t032', 'frase', 'A2', array['trecho']::text[], null, 'b1870bca', array['«Por que», diz ele, «tornas turva para mim', '«Por que», diz ele, «tornaste turva para mim', '«Por que», diz ele, «tornaste turvo para mim', '«Por que», diz ele, «torno turva para ti', '«Por que», dizem eles, «tornastes turva para mim']::text[]),
  ('la-pt', 'la-t033', 'frase', 'A2', array['trecho']::text[], null, 'cfc0819a', array['a água que bebes? O lanígero, em resposta, temendo:', 'a água, enquanto bebia? O lanígero, contra o medo:', 'a água, enquanto bebo? Os lanígeros, em resposta, temendo:', 'a água, enquanto bebo?» O lanígero, em resposta, temendo:', 'as águas, enquanto bebo? O lanígero, em resposta, temendo:']::text[]),
  ('la-pt', 'la-t034', 'frase', 'A2', array['trecho']::text[], null, '63b3f166', array['«Como podes, por favor, fazer aquilo de que me queixo, lobo?', '«Como posso, por favor, fazer aquilo de que os lobos se queixam?', '«Como posso, por favor, fazer aquilo de que te queixas, lobo?', '«Como pude, por favor, fazer aquilo de que te queixas, lobo?', '«Quem pode, por favor, fazer aquilo de que te queixas, lobo?']::text[]),
  ('la-pt', 'la-t035', 'frase', 'A2', array['trecho']::text[], null, '4b69c4b4', array['De mim desce a água até os teus goles.', 'De ti desce a água até os meus goles.»', 'De ti descem as águas até o meu gole.', 'De ti desceu a água até os meus goles.', 'Para ti desce a água dos meus goles.']::text[]),
  ('la-pt', 'la-u126', 'frase', 'A1', array['frase de uso']::text[], 'la-p004', '975d958e', array['Nisso estava tudo para mim.', 'Nisso está tudo para mim.', 'Nisso está tudo para ti.', 'Nisso eu sou tudo.', 'Tudo está em mim.']::text[]),
  ('la-pt', 'la-u127', 'frase', 'A1', array['frase de uso']::text[], 'la-p008', '552cbe79', array['Prepara o caminho do Senhor.', 'Preparai o caminho do Senhor.', 'Preparai o caminho para o Senhor.', 'Preparai os caminhos do Senhor.', 'Preparou o caminho do Senhor.']::text[]),
  ('la-pt', 'la-u128', 'frase', 'A1', array['frase de uso']::text[], 'la-p012', '6e0b04f4', array['O Senhor é o nosso Deus.', 'Senhor, nós somos o teu Deus.', 'Senhor, tu eras o nosso Deus.', 'Senhor, tu és o nosso Deus.', 'Senhor, vós sois o nosso Deus.']::text[]),
  ('la-pt', 'la-u129', 'frase', 'A1', array['frase de uso']::text[], 'la-p018', '947b1d49', array['e Deus os louvou.', 'e louvamos a Deus.', 'e louvaram a Deus.', 'e louvarão a Deus.', 'e louvou a Deus.']::text[]),
  ('la-pt', 'la-u130', 'frase', 'A1', array['frase de uso']::text[], 'la-p021', '6be945de', array['Não eras, acredita em mim.', 'Não sou, acredita em mim.', 'Não és, acredita em mim.', 'Não és, acreditai em mim.', 'Não és, acredito em ti.']::text[]),
  ('la-pt', 'la-u131', 'frase', 'A1', array['frase de uso']::text[], 'la-p022', 'c7cde51e', array['Em ti esperamos, ó nossos pais.', 'Em ti esperaram os nossos pais.', 'Em ti esperarão os nossos pais.', 'Em ti esperou o nosso pai.', 'Tu esperaste nos nossos pais.']::text[]),
  ('la-pt', 'la-u132', 'frase', 'A1', array['frase de uso']::text[], 'la-p025', '2320e85e', array['eu sou o dia.', 'o dia era meu.', 'o dia é meu.', 'o dia é teu.', 'os dias são meus.']::text[]),
  ('la-pt', 'la-u133', 'frase', 'A1', array['frase de uso']::text[], 'la-p026', '637c5a17', array['Venceram pelas armas, foram vencidos pelos vícios.', 'Vencerá pelas armas, será vencido pelos vícios.', 'Venceu as armas, foi vencido pelos vícios.', 'Venceu pelas armas, foi vencido pelos vícios.', 'Venceu pelas armas, venceu os vícios.']::text[]),
  ('la-pt', 'la-u134', 'frase', 'A1', array['frase de uso']::text[], 'la-p030', 'f5fc03ea', array['pois não te venci em amor.', 'pois não te venço em amor.', 'pois não vos venço em amor.', 'pois o amor não te vence.', 'pois tu não me vences em amor.']::text[]),
  ('la-pt', 'la-u135', 'frase', 'A1', array['frase de uso']::text[], 'la-p031', '8bf62af0', array['não era inimigo do Amor.', 'não sou inimigo do Amor.', 'não é inimigo do Amor.', 'não é inimigo dos amores.', 'o Amor não é inimigo.']::text[]),
  ('la-pt', 'la-u137', 'frase', 'A1', array['frase de uso']::text[], 'la-p037', 'cdd29ca2', array['se queres amar, ama.', 'se queres amar, sê amado.', 'se queres ser amado, ama.', 'se queres ser amado, amai.', 'se quero ser amado, amo.']::text[]),
  ('la-pt', 'la-u138', 'frase', 'A1', array['frase de uso']::text[], 'la-p045', 'd893f156', array['Também estas coisas viram os dias da minha vaidade.', 'Também verei estas coisas nos dias da minha vaidade.', 'Também vi estas coisas no dia da minha vaidade.', 'Também vi estas coisas nos dias da minha vaidade.', 'Também vi estas coisas nos dias da tua vaidade.']::text[]),
  ('la-pt', 'la-u139', 'frase', 'A1', array['frase de uso']::text[], 'la-p055', '619a2125', array['A tua terra abençoou o Senhor.', 'Abençoarás, Senhor, a tua terra.', 'Abençoaste, Senhor, a tua terra.', 'Abençoaste, Senhor, as tuas terras.', 'Abençoei, Senhor, a tua terra.']::text[]),
  ('la-pt', 'la-u140', 'frase', 'A1', array['frase de uso']::text[], 'la-p073', '9e46acf2', array['a mão está no ferro.', 'o ferro estava na mão.', 'o ferro está na mão.', 'o ferro está nas mãos.', 'o ferro é a mão.']::text[]),
  ('la-pt', 'la-u141', 'frase', 'A1', array['frase de uso']::text[], 'la-p074', '540fd716', array['ele me recomenda a eles.', 'ele os recomenda a mim.', 'ele os recomendou a mim.', 'eles os recomendam a mim.', 'eu os recomendo a ti.']::text[]),
  ('la-pt', 'la-u142', 'frase', 'A1', array['frase de uso']::text[], 'la-p075', '6a8ed6af', array['Onde estás tu?', 'Para onde foste tu?', 'Para onde ides vós?', 'Para onde vais tu?', 'Para onde vou eu?']::text[]),
  ('la-pt', 'la-u143', 'frase', 'A1', array['frase de uso']::text[], 'la-p088', '9fbfd839', array['A glória do Senhor está no século.', 'A glória do Senhor foi para sempre.', 'A glória do Senhor seja para sempre.', 'A glória dos senhores seja para sempre.', 'O Senhor da glória seja para sempre.']::text[]),
  ('la-pt', 'la-u144', 'frase', 'A1', array['frase de uso']::text[], 'la-p093', 'b4135d14', array['Ainda não cheguei ao meu tempo.', 'O meu tempo ainda não chegará.', 'O meu tempo ainda não chegou.', 'O teu tempo ainda não chegou.', 'Os meus tempos ainda não chegaram.']::text[]),
  ('la-pt', 'la-u146', 'frase', 'A1', array['frase de uso']::text[], 'la-p102', '6df7e0ea', array['Paga, pois, a todos a dívida.', 'Pagai, pois, a todos a dívida.', 'Pagai, pois, a todos as dívidas.', 'Pagai, pois, as dívidas de todos.', 'Pagaram, pois, a todos as dívidas.']::text[]),
  ('la-pt', 'la-u147', 'frase', 'A1', array['frase de uso']::text[], 'la-p109', '94c4ef60', array['Não vieram males sobre nós.', 'Não virá o mal sobre nós.', 'Não virão males sobre nós.', 'Não virão males sobre vós.', 'Não vêm males sobre nós.']::text[]),
  ('la-pt', 'la-u149', 'frase', 'A1', array['frase de uso']::text[], 'la-p111', '0efe7019', array['A vida era longa, se era cheia.', 'A vida seria longa, se fosse cheia.', 'A vida é cheia, se é longa.', 'A vida é longa, se é cheia.', 'As vidas são longas, se são cheias.']::text[]),
  ('la-pt', 'la-u150', 'frase', 'A1', array['frase de uso']::text[], 'la-p113', '0efcea7d', array['Era bom para o homem não tocar mulher.', 'É bom para a mulher não tocar o homem.', 'É bom para o homem não ser tocado pela mulher.', 'É bom para o homem não tocar mulher.', 'É bom para os homens não tocar mulheres.']::text[]),
  ('la-pt', 'la-u151', 'frase', 'A1', array['frase de uso']::text[], 'la-p114', '89ab9358', array['A recompensa é o fruto para o ventre.', 'O fruto do ventre era uma recompensa.', 'O fruto do ventre é uma recompensa.', 'O ventre do fruto é uma recompensa.', 'Os frutos do ventre são uma recompensa.']::text[]),
  ('la-pt', 'la-u152', 'frase', 'A1', array['frase de uso']::text[], 'la-p116', 'a1c43e58', array['Honra o pai da tua mãe.', 'Honra o teu pai e a tua mãe.', 'Honrai o vosso pai e a vossa mãe.', 'Honrou o teu pai e a tua mãe.', 'O teu pai e a tua mãe te honram.']::text[]),
  ('la-pt', 'la-u153', 'frase', 'A1', array['frase de uso']::text[], 'la-p126', '75fd0af4', array['Chegaram a tempo.', 'Chegaste a tempo.', 'Cheguei a tempo.', 'Venho a tempo.', 'Virei a tempo.']::text[]),
  ('la-pt', 'la-u154', 'frase', 'A1', array['frase de uso']::text[], 'la-p127', '6c2c9946', array['Fogem e não veem o bem.', 'Fugiram e não viram o bem.', 'Fugiram e não viram os bens.', 'Fugiremos e não veremos o bem.', 'Fugiu e não viu o bem.']::text[]),
  ('la-pt', 'la-u155', 'frase', 'A1', array['frase de uso']::text[], 'la-p128', '357b43fa', array['Os que cantam com arte, cantem.', 'Quem canta a arte, cante.', 'Quem canta com arte, canta.', 'Quem canta com arte, cante.', 'Quem cantou com arte, cante.']::text[]),
  ('la-pt', 'la-u156', 'frase', 'A1', array['frase de uso']::text[], 'la-p129', 'cd04f256', array['Não era longo.', 'Não será longo.', 'Não sou longo.', 'Não são longos.', 'Não é longo.']::text[]),
  ('la-pt', 'la-u157', 'frase', 'A1', array['frase de uso']::text[], 'la-p130', 'ee5ed91c', array['Breve é o dia do homem.', 'Breves eram os dias do homem.', 'Breves são os dias do homem.', 'Breves são os dias dos homens.', 'Os dias são breves para o homem.']::text[]),
  ('la-pt', 'la-u158', 'frase', 'A1', array['frase de uso']::text[], 'la-p131', 'afbaa2bf', array['Tenho boa esperança, enquanto é permitido.', 'Terei boa esperança, enquanto for permitido.', 'Teremos boa esperança, enquanto for permitido.', 'Terás boa esperança, enquanto for permitido.', 'Tive boa esperança, enquanto foi permitido.']::text[]),
  ('la-pt', 'la-u159', 'frase', 'A1', array['frase de uso']::text[], 'la-p133', '71910db7', array['Em mim, Senhor, esperaste.', 'Em ti, Senhor, esperaram.', 'Em ti, Senhor, esperarei.', 'Em ti, Senhor, esperei.', 'Em ti, Senhor, espero.']::text[]),
  ('la-pt', 'la-u160', 'frase', 'A1', array['frase de uso']::text[], 'la-p134', '6dd689d5', array['Pensam estas coisas, e erram.', 'Pensaram estas coisas, e erraram.', 'Pensaremos estas coisas, e erraremos.', 'Pensastes estas coisas, e errastes.', 'Pensou estas coisas, e errou.']::text[]),
  ('la-pt', 'la-u161', 'frase', 'A1', array['frase de uso']::text[], 'la-p135', 'f407c72b', array['A minha mão, pois, não estava sobre ti.', 'A minha mão, pois, não está sobre ti.', 'Que a minha mão, pois, não esteja sobre ti.', 'Que a tua mão, pois, não esteja sobre mim.', 'Que as minhas mãos, pois, não estejam sobre ti.']::text[]),
  ('la-pt', 'la-u162', 'frase', 'A1', array['frase de uso']::text[], 'la-p136', 'ddf5aa82', array['Creio que terei medo e, ensinado, tomarei cuidado.', 'Creio que tereis medo e, ensinados, tomareis cuidado.', 'Creio que terás medo e, ensinado, tomarás cuidado.', 'Creio que terás medo e, ensinando, tomarás cuidado.', 'Creio que tiveste medo e, ensinado, tomaste cuidado.']::text[]),
  ('la-pt', 'la-u163', 'frase', 'A1', array['frase de uso']::text[], 'la-p137', 'a40f38cd', array['Enquanto hesita, o cão o viu.', 'Enquanto hesita, os cães o veem.', 'Enquanto hesita, os cães o viram.', 'Enquanto hesita, viu os cães.', 'Enquanto hesitam, os cães o viram.']::text[]),
  ('la-pt', 'la-u164', 'frase', 'A1', array['frase de uso']::text[], 'la-p138', 'e67500c5', array['Os que sabem são sábios.', 'Quem sabe será sábio.', 'Quem sabe é sábio.', 'Quem sabia é sábio.', 'Quem é sábio sabe.']::text[]),
  ('la-pt', 'la-u165', 'frase', 'A1', array['frase de uso']::text[], 'la-p139', '63ef8d39', array['Acredita em mim, não ousarei.', 'Acredita em mim, não ousarás.', 'Acredita em mim, não ousaste.', 'Acreditai em mim, não ousareis.', 'Acredito em ti, não ousarás.']::text[]),
  ('la-pt', 'la-u166', 'frase', 'A1', array['frase de uso']::text[], 'la-p142', '8e78a16b', array['Os que crerem não se apressem.', 'Quem crer não se apresse.', 'Quem crer não se apressou.', 'Quem creu não se apressa.', 'Quem não crer se apresse.']::text[]),
  ('la-pt', 'la-u167', 'frase', 'A1', array['frase de uso']::text[], 'la-p144', '4e4bfb25', array['Não temos vinho.', 'Não tinham vinho.', 'Não têm vinho.', 'Não têm vinhos.', 'O vinho não os tem.']::text[]),
  ('la-pt', 'la-u168', 'frase', 'A1', array['frase de uso']::text[], 'la-p146', '7c4fefe6', array['Ai da minha mãe!', 'Ai de mim, minha mãe!', 'Ai de mim, nossa mãe!', 'Ai de nós, minha mãe!', 'Ai de ti, minha mãe!']::text[]),
  ('la-pt', 'la-u169', 'frase', 'A1', array['frase de uso']::text[], 'la-p147', '0c45590a', array['A necessidade de combater, da qual fugis, nos seguirá.', 'A necessidade de combater, da qual fugis, vos seguia.', 'A necessidade de combater, da qual fugis, vos seguirá.', 'A necessidade de combater, que vos foge, vos seguirá.', 'Seguireis a necessidade de combater, da qual fugis.']::text[]),
  ('la-pt', 'la-u170', 'frase', 'A1', array['frase de uso']::text[], 'la-p148', '084ebeb1', array['A alma é boa, e o corpo, e a fortuna.', 'Havia bens da alma, havia do corpo, havia da fortuna.', 'Há bens da alma, há do corpo, há da fortuna.', 'Há bens para a alma, para o corpo, para a fortuna.', 'Há o bem da alma, há o do corpo, há o da fortuna.']::text[]),
  ('la-pt', 'la-u171', 'frase', 'A1', array['frase de uso']::text[], 'la-p149', 'f56a5a88', array['Quanto ao que resta, ajudemos os deuses!', 'Quanto ao que resta, os deuses ajudam!', 'Quanto ao que resta, os deuses ajudaram!', 'Quanto ao que resta, que o deus ajude!', 'Quanto ao que resta, que os deuses ajudem!']::text[]),
  ('la-pt', 'la-u172', 'frase', 'A1', array['frase de uso']::text[], 'la-p152', 'b9b25c5b', array['A pedra, pois, os tirou.', 'Tiram, pois, a pedra.', 'Tiraram, pois, a pedra.', 'Tiraram, pois, as pedras.', 'Tirou, pois, a pedra.']::text[]),
  ('la-pt', 'la-u173', 'frase', 'A1', array['frase de uso']::text[], 'la-p153', '7a95ddf0', array['A fábula do lobo.', 'Ao lobo, a fábula.', 'O lobo na fábula.', 'O lobo para dentro da fábula.', 'Os lobos na fábula.']::text[]),
  ('la-pt', 'la-u174', 'frase', 'A1', array['frase de uso']::text[], 'la-p154', '5fec2150', array['O homem te verá, pois, se quiseres.', 'Verei, pois, o homem, se quiser.', 'Verás, pois, o homem, se quiseres.', 'Verás, pois, os homens, se quiseres.', 'Viste, pois, o homem, se quiseste.']::text[]),
  ('la-pt', 'la-u175', 'frase', 'A1', array['frase de uso']::text[], 'la-p155', 'f4a2a701', array['Deus quer ser feito.', 'Quer fazer um deus.', 'Quer tornar-se deus.', 'Querem tornar-se deuses.', 'Queria tornar-se deus.']::text[]),
  ('la-pt', 'la-u176', 'frase', 'A1', array['frase de uso']::text[], 'la-p156', 'b90bfa76', array['Eu estava pronto.', 'Eu estou pronto.', 'Eu preparei.', 'Nós estamos prontos.', 'Tu estás pronto.']::text[]),
  ('la-pt', 'la-u177', 'frase', 'A1', array['frase de uso']::text[], 'la-p157', '2f6d3235', array['Pois a guerra foi do Senhor.', 'Pois a guerra foi para o Senhor.', 'Pois a guerra será do Senhor.', 'Pois as guerras foram do Senhor.', 'Pois o Senhor foi da guerra.']::text[]),
  ('la-pt', 'la-u178', 'frase', 'A1', array['frase de uso']::text[], 'la-p158', '0f1cbffa', array['Se erraste, ensina-me tu.', 'Se errei, ensina-me tu.', 'Se errei, ensinai-me vós.', 'Se errei, eu te ensino.', 'Se erro, ensina-me tu.']::text[]),
  ('la-pt', 'la-u179', 'frase', 'A1', array['frase de uso']::text[], 'la-p159', '5c35a336', array['Não quer aprender.', 'O querer não aprende.', 'O querer não se aprende.', 'O querer não se aprendia.', 'Os quereres não se aprendem.']::text[]),
  ('la-pt', 'la-u180', 'frase', 'A1', array['frase de uso']::text[], 'la-p160', '3fac2b56', array['Dirão bem todas as coisas.', 'Disse bem todas as coisas.', 'Disseram bem de todos.', 'Disseram bem todas as coisas.', 'Todas as coisas disseram bem.']::text[]),
  ('la-pt', 'la-u181', 'frase', 'A1', array['frase de uso']::text[], 'la-p161', '4b163477', array['a pátria nos foge.', 'eu fujo da pátria.', 'nós fugimos da pátria.', 'nós fugimos para a pátria.', 'nós fugíamos da pátria.']::text[]),
  ('la-pt', 'la-u183', 'frase', 'A1', array['frase de uso']::text[], 'la-p163', '198d82df', array['Nós, portanto, erramos muito.', 'Tu, portanto, erras muito.', 'Vós, portanto, errais muito.', 'Vós, portanto, errastes muito.', 'Vós, portanto, erráveis muito.']::text[]),
  ('la-pt', 'la-u184', 'frase', 'A1', array['frase de uso']::text[], 'la-p164', '87bebe2c', array['as armas nos odeiam.', 'eu odeio as armas.', 'nós odiamos as armas.', 'nós odiaremos as armas.', 'nós odiávamos as armas.']::text[]),
  ('la-pt', 'la-u185', 'frase', 'A1', array['frase de uso']::text[], 'la-p165', 'b113da59', array['fareis tudo para a glória de Deus.', 'faze tudo para a glória de Deus.', 'fazei tudo para a glória de Deus.', 'fizestes tudo para a glória de Deus.', 'tudo faz a glória de Deus.']::text[]),
  ('la-pt', 'la-u186', 'frase', 'A1', array['frase de uso']::text[], 'la-p166', '3fcf4875', array['Talvez eu não venha.', 'Talvez não tenha vindo.', 'Talvez não venha.', 'Talvez não venham.', 'Talvez não viesse.']::text[]),
  ('la-pt', 'la-u187', 'frase', 'A1', array['frase de uso']::text[], 'la-p167', '3a2374e3', array['Todos procuram a arma.', 'Todos procuram as armas.', 'Todos procuraram as armas.', 'Todos procurarão as armas.', 'Todos procuravam as armas.']::text[]),
  ('la-pt', 'la-u189', 'frase', 'A1', array['frase de uso']::text[], 'la-p169', 'e1caca63', array['e o deus sente isso.', 'e o deus sentirá isso.', 'e o deus sentiu isso.', 'e os deuses sentem isso.', 'e tu, ó deus, sentes isso.']::text[]),
  ('la-pt', 'la-u190', 'frase', 'A1', array['frase de uso']::text[], 'la-p170', '6eb1bdd6', array['Estas coisas me torturam.', 'Estas coisas me torturaram.', 'Estas coisas me torturarão.', 'Estas coisas te torturam.', 'Eu torturo estas coisas.']::text[]),
  ('la-pt', 'la-u191', 'frase', 'A1', array['frase de uso']::text[], 'la-p171', '565018b5', array['Por que, então, ele não creu em vós?', 'Por que, então, não credes nele?', 'Por que, então, não crestes nele?', 'Por que, então, não crestes neles?', 'Por que, então, não crês nele?']::text[]),
  ('la-pt', 'la-u192', 'frase', 'A1', array['frase de uso']::text[], 'la-p172', 'f6431aea', array['Diz-me: quem levarás, ó rainha das aves?', 'Diz-me: quem levas, ó rainha das aves?', 'Diz-me: quem levavas, ó rainha das aves?', 'Diz-me: quem te leva, ó rainha das aves?', 'Dizei-me: quem levais, ó rainhas das aves?']::text[]),
  ('la-pt', 'la-u193', 'frase', 'A1', array['frase de uso']::text[], 'la-p173', '55438748', array['Eu vi e me alegrei.', 'Tu viste e ele se alegrou.', 'Tu viste e te alegras.', 'Tu viste e te alegraste.', 'Vós vistes e vos alegrastes.']::text[]),
  ('la-pt', 'la-u194', 'frase', 'A1', array['frase de uso']::text[], 'la-p174', 'c8cbee33', array['Porque vieram dias sobre ti.', 'Porque virá um dia sobre ti.', 'Porque virão dias sobre mim.', 'Porque virão dias sobre ti.', 'Porque vêm dias sobre ti.']::text[]),
  ('la-pt', 'la-u195', 'frase', 'A1', array['frase de uso']::text[], 'la-p175', '60582485', array['Os deuses e tu me deram o que quero, se mereci.', 'Que os deuses e tu me deem o que quero, se mereceres.', 'Que os deuses e tu me deem o que quero, se mereci.', 'Que os deuses e tu me deem o que quero, se mereço.', 'Que os deuses e tu te deem o que queres, se mereceste.']::text[]),
  ('la-pt', 'la-u196', 'frase', 'A1', array['frase de uso']::text[], 'la-p176', 'b375837b', array['eu carregarei e salvarei.', 'eu carregava e salvava.', 'eu carrego e salvo.', 'eu carreguei e salvei.', 'tu carregarás e salvarás.']::text[]),
  ('la-pt', 'la-u197', 'frase', 'A1', array['frase de uso']::text[], 'la-p177', '9f15b997', array['Estava bem: Troia ressurgia.', 'Está bem: Troia ressurge.', 'Está bem: Troia ressurgirá.', 'Está bem: Troia ressurgiu.', 'Está bem: tu ressurges, Troia.']::text[]),
  ('la-pt', 'la-u198', 'frase', 'A1', array['frase de uso']::text[], 'la-p178', '26aaebe7', array['Fui e vim a vós.', 'Ide e vinde a mim.', 'Irei e virei a vós.', 'Vou e venho a vós.', 'Vou e venho de vós.']::text[]),
  ('la-pt', 'la-u200', 'frase', 'A1', array['frase de uso']::text[], 'la-p180', 'dbda3bbd', array['Eu estarei nas mesmas armas.', 'Eu estive na mesma arma.', 'Eu estive nas mesmas armas.', 'Eu estou nas mesmas armas.', 'Tu estiveste nas mesmas armas.']::text[]),
  ('la-pt', 'la-u201', 'frase', 'A1', array['frase de uso']::text[], 'la-p181', 'a5079ace', array['Apascenta o meu cordeiro.', 'Apascenta os meus cordeiros.', 'Apascentai os meus cordeiros.', 'Apascentei os meus cordeiros.', 'Os meus cordeiros apascentam.']::text[]),
  ('la-pt', 'la-u202', 'frase', 'A1', array['frase de uso']::text[], 'la-p182', 'e4943da0', array['A minha sede era sã.', 'A minha sede é sã.', 'Que a minha sede seja sã.', 'Que a tua sede seja sã.', 'Que as minhas sedes sejam sãs.']::text[]),
  ('la-pt', 'la-u203', 'frase', 'A1', array['frase de uso']::text[], 'la-p183', '4d58d099', array['e agora viemos a vós, forçados pela necessidade.', 'e agora vieste a mim, forçado pela necessidade.', 'e agora viestes a mim, forçados pela necessidade.', 'e agora viestes a mim, forçando a necessidade.', 'e agora vindes a mim, forçados pela necessidade.']::text[]),
  ('la-pt', 'la-u205', 'frase', 'A1', array['frase de uso']::text[], 'la-p185', '533cf794', array['E eu vim ao Senhor e fiquei de pé.', 'E o Senhor veio e ficou de pé.', 'E o Senhor vem e fica de pé.', 'E o Senhor virá e ficará de pé.', 'E vieram os senhores e ficaram de pé.']::text[]),
  ('la-pt', 'la-u206', 'frase', 'A1', array['frase de uso']::text[], 'la-p186', '4f617d53', array['De longe eu apareci ao Senhor.', 'De longe o Senhor me aparecerá.', 'De longe o Senhor me apareceu.', 'De longe o Senhor te apareceu.', 'De longe os senhores me apareceram.']::text[]),
  ('la-pt', 'la-u207', 'frase', 'A1', array['frase de uso']::text[], 'la-p187', 'a8bece6d', array['nem era inferior a vós.', 'nem sois inferiores a mim.', 'nem sou inferior a ti.', 'nem sou inferior a vós.', 'nem és inferior a nós.']::text[]),
  ('la-pt', 'la-u208', 'frase', 'A1', array['frase de uso']::text[], 'la-p188', 'f5c4b01b', array['Então verei, e transbordarei.', 'Então vereis, e transbordareis.', 'Então verás, e transbordarás.', 'Então viste, e transbordaste.', 'Então vês, e transbordas.']::text[]),
  ('la-pt', 'la-u209', 'frase', 'A1', array['frase de uso']::text[], 'la-p190', '686f3f62', array['E foi repelido pelo perverso.', 'E o perverso repeliu.', 'E repele o perverso.', 'E repeliu o perverso.', 'E repeliu os perversos.']::text[]),
  ('la-pt', 'la-u213', 'frase', 'A1', array['frase de uso']::text[], 'la-p194', '182ba19e', array['O amor era para mim a causa de seguir.', 'O amor é para mim a causa de seguir.', 'O amor é para mim a causa de ser seguido.', 'O amor é para ti a causa de seguir.', 'Os amores são para mim a causa de seguir.']::text[]),
  ('la-pt', 'la-u214', 'frase', 'A1', array['frase de uso']::text[], 'la-p195', '9f878dd1', array['A Dolópia levou a guerra.', 'Leva a guerra à Dolópia.', 'Levaram a guerra à Dolópia.', 'Levou a guerra da Dolópia.', 'Levou a guerra à Dolópia.']::text[]),
  ('la-pt', 'la-u215', 'frase', 'A1', array['frase de uso']::text[], 'la-p196', 'a7c8b5b4', array['Por que eu não estarei contigo?', 'Por que eu não estava contigo?', 'Por que eu não estou contigo?', 'Por que nós não estamos contigo?', 'Por que tu não estás comigo?']::text[]),
  ('la-pt', 'la-u216', 'frase', 'A1', array['frase de uso']::text[], 'la-p197', '73852db2', array['Sois nossos servos, dizem eles.', 'Somos teus servos, diz ele.', 'Somos teus servos, dizem eles.', 'Somos teus servos, dizemos.', 'Éramos teus servos, dizem eles.']::text[]),
  ('la-pt', 'la-u217', 'frase', 'A1', array['frase de uso']::text[], 'la-p198', '80ca4895', array['A mim, ao menos, parece que foi turbulento.', 'A mim, ao menos, parecem que vão ser turbulentos.', 'A mim, ao menos, pareciam que iam ser turbulentos.', 'Eles, ao menos, me veem turbulento.', 'Eu, ao menos, pareço que vou ser turbulento.']::text[]),
  ('la-pt', 'la-u218', 'frase', 'A1', array['frase de uso']::text[], 'la-p199', '83ad6b54', array['A água te viu, e temeu.', 'As águas te veem, e temem.', 'As águas te verão, e temerão.', 'As águas te viram, e temeram.', 'Tu viste as águas, e temeste.']::text[]),
  ('la-pt', 'la-u219', 'frase', 'A1', array['frase de uso']::text[], 'la-p200', 'b4a4063f', array['Bebe, meu senhor.', 'Bebei, meus senhores.', 'Bebeste, meu senhor.', 'Bebo, meu senhor.', 'O meu senhor bebe.']::text[]),
  ('la-pt', 'la-u221', 'frase', 'A1', array['frase de uso']::text[], 'la-p202', 'c78cebf3', array['Tramam contra mim.', 'Tramaram contra mim.', 'Tramaram contra ti.', 'Tramará contra mim.', 'Tramei contra eles.']::text[]),
  ('la-pt', 'la-u222', 'frase', 'A1', array['frase de uso']::text[], 'la-p203', '0b09a710', array['Não temer o homem, nem o deus.', 'Não temer os homens, nem os deuses.', 'Não temeram os homens, nem os deuses.', 'Não temo os homens, nem os deuses.', 'Os homens não temem os deuses.']::text[]),
  ('la-pt', 'la-u223', 'frase', 'A1', array['frase de uso']::text[], 'la-p204', '1d745121', array['Nós, por favor, apressamo-nos a vir até ti.', 'Tu, por favor, apressa-te a vir até nós.', 'Tu, por favor, apressaste-te a vir até nós.', 'Tu, por favor, demoras a vir até nós.', 'Vós, por favor, apressai-vos a vir até nós.']::text[]),
